function update(){recompute();$('currentToggle').checked=state.showCurrent;renderBoard();renderReadings();renderProperties();updateHistoryButtons();audio.sync(state.components,solution.components,store.data.settings);saveSoon();}
function renderLibrary(){$('libraryCount').textContent=`${Object.keys(definitions).length} 种元件`;$('componentLibrary').innerHTML=Object.entries(definitions).map(([type,d])=>`<button class="component-card" data-add="${type}" draggable="true" aria-label="添加${d.name}"><span class="component-thumb">${thumbnail(type)}</span><span><strong>${d.name}</strong></span></button>`).join('');}
function setTool(next){tool=next;pendingTerminal=null;document.querySelectorAll('button[data-tool]').forEach(el=>{el.classList.toggle('active',el.dataset.tool===tool);el.setAttribute('aria-pressed',String(el.dataset.tool===tool));});$('boardHint').innerHTML=icon(tool==='junction'?'junction':tool==='erase'?'eraser':'cursor')+`<span>${tool==='junction'?'点击空白放节点 · 点击接线端/节点连接 · 拖动空白移动画布':tool==='erase'?'点击删除元件、导线或节点 · 拖动空白移动画布':'选择或移动元件 · 拖动空白移动画布 · 滚轮缩放'}</span>`;$('board').dataset.tool=tool;renderPreview();}
function select(id){selected=id;renderBoard();renderProperties();}
function toggleSwitch(id){const c=getComponent(id);if(!['switch','spdt'].includes(c?.type))return;lastSwitchClick=null;pushHistory();selected=c.id;pendingTerminal=null;if(c.type==='spdt')c.position=c.position===1?2:1;else c.closed=!c.closed;update();}
function addComponent(type,point){if(!Object.hasOwn(definitions,type))return;if(state.components.length>=200){toast('元件较多，请先保存当前实验后继续其他实验。');return;}pushHistory();const num=state.components.filter(c=>c.type===type).reduce((m,c)=>Math.max(m,Number(c.id.slice(1))),0)+1,prefix=definitions[type].idPrefix??({battery:'e',lamp:'l',resistor:'r',switch:'s',ammeter:'a',voltmeter:'v'}[type]??type[0]);const p=point??{x:camera.x+((state.nextId%3)-1)*110,y:camera.y+((Math.floor(state.nextId/3)%2)?45:-45)};const c=component(`${prefix}${num}`,type,Math.round(p.x/10)*10,Math.round(p.y/10)*10,undefined,0);state.components.push(c);state.nextId++;state.preset='free';selected=c.id;setTool('select');update();}
function clearRoutes(id){for(const w of state.wires)if(w.a.startsWith(id+':')||w.b.startsWith(id+':'))delete w.via;}
function deleteSelected(id=selected){if(!id)return;pushHistory();if(getWire(id))state.wires=state.wires.filter(w=>w.id!==id);else{state.components=state.components.filter(c=>c.id!==id);state.junctions=state.junctions.filter(n=>n.id!==id);state.wires=state.wires.filter(w=>!w.a.startsWith(id+':')&&!w.b.startsWith(id+':'));}selected=null;pendingTerminal=null;state.preset='free';update();}
function nextWire(){return `w${Date.now()}${state.nextId++}`;}
function connectTerminal(key){if(!pendingTerminal){pendingTerminal=key;renderBoard();return;}if(pendingTerminal===key){pendingTerminal=null;renderBoard();return;}if(state.wires.some(w=>(w.a===pendingTerminal&&w.b===key)||(w.b===pendingTerminal&&w.a===key))){pendingTerminal=null;renderBoard();toast('这两个接线端已经连接');return;}if(state.wires.length>=1000){toast('导线较多，请保存并整理当前实验。');return;}pushHistory();state.wires.push({id:nextWire(),a:pendingTerminal,b:key});pendingTerminal=null;state.preset='free';update();if(solution.status==='short')toast('检测到电源短路，请断开跨接导线或串入电阻。');}
function placeJunction(point,wireId=null){
  const source=pendingTerminal,target=getWire(wireId),hit=target&&projectOnWire(target,point,terminalPoint);if(target&&!hit)return;const p=hit?.point??{x:Math.round(point.x/10)*10,y:Math.round(point.y/10)*10};
  if(target){const key=[target.a,target.b].find(k=>{const t=terminalPoint(k);return Math.hypot(t.x-p.x,t.y-p.y)<1;});if(key){connectTerminal(key);return;}}
  const existing=state.junctions.find(n=>Math.hypot(n.x-p.x,n.y-p.y)<(target?.1:6)),key=existing?`${existing.id}:0`:null,crossing=target?state.wires.filter(w=>{const h=projectOnWire(w,p,terminalPoint);return h&&h.distance<.1&&splitWire(w,p,terminalPoint,'candidate:0','candidate');}):[];
  if((!existing&&state.junctions.length>=500)||state.wires.length+crossing.length+(source?1:0)>1000){toast('节点或导线较多，请先保存当前实验。');return;}
  if(existing&&!source&&!target){select(existing.id);return;}
  pushHistory();const n=existing??{id:`n${state.nextId++}`,x:p.x,y:p.y};if(!existing)state.junctions.push(n);const terminal=`${n.id}:0`,ids=new Set(crossing.map(w=>w.id));state.wires=state.wires.flatMap(w=>ids.has(w.id)?splitWire(w,p,terminalPoint,terminal,nextWire())?.wires??[w]:[w]);
  if(source&&source!==terminal&&!state.wires.some(w=>(w.a===source&&w.b===terminal)||(w.b===source&&w.a===terminal)))state.wires.push({id:nextWire(),a:source,b:terminal});
  selected=n.id;pendingTerminal=null;state.preset='free';update();
}

$('board').addEventListener('pointerdown',event=>{
  if(event.button!==0&&event.button!==1)return;const terminal=event.target.closest('[data-terminal]'),node=event.target.closest('[data-junction]'),comp=event.target.closest('[data-component]'),wire=event.target.closest('[data-wire]');const id=node?.dataset.junction??comp?.dataset.component??wire?.dataset.wire??terminal?.dataset.ownerComponent;
  if(event.button!==0||!comp||!['switch','spdt'].includes(getComponent(id)?.type))lastSwitchClick=null;
  if(event.button===1){event.preventDefault();gesture={kind:'pan',startX:event.clientX,startY:event.clientY,camera:{...camera},scale:viewportGeometry(camera,zoom,$('boardWrap').getBoundingClientRect()).scale,moved:false};$('board').setPointerCapture(event.pointerId);return;}
  if(tool==='erase'&&id){deleteSelected(id);return;}
  if(tool==='junction'&&terminal){connectTerminal(terminal.dataset.terminal);return;}
  if(tool==='junction'&&wire){placeJunction(pointFromEvent(event),wire.dataset.wire);return;}
  if(id){pendingTerminal=null;selected=id;renderProperties();renderBoard();if(comp||node){const p=pointFromEvent(event),item=getItem(id);gesture={kind:'item',id,offsetX:p.x-item.x,offsetY:p.y-item.y,startX:event.clientX,startY:event.clientY,before:clone(state),moved:false};$('board').setPointerCapture(event.pointerId);}return;}
  gesture={kind:'blank',startX:event.clientX,startY:event.clientY,camera:{...camera},scale:viewportGeometry(camera,zoom,$('boardWrap').getBoundingClientRect()).scale,moved:false};$('board').setPointerCapture(event.pointerId);
});
$('board').addEventListener('pointermove',event=>{lastPointer=pointFromEvent(event);if(!gesture){renderPreview();return;}const dx=event.clientX-gesture.startX,dy=event.clientY-gesture.startY;if(!gesture.moved&&Math.hypot(dx,dy)<4)return;gesture.moved=true;if(gesture.kind==='item'){const item=getItem(gesture.id);item.x=Math.round((lastPointer.x-gesture.offsetX)/10)*10;item.y=Math.round((lastPointer.y-gesture.offsetY)/10)*10;clearRoutes(item.id);renderBoard();}else{camera=panCamera(gesture.camera,dx,dy,gesture.scale);$('boardWrap').classList.add('is-panning');updateViewport();}});
function finishGesture(event,cancelled=false){if(!gesture)return;const current=gesture;gesture=null;$('boardWrap').classList.remove('is-panning');if(cancelled||current.moved)lastSwitchClick=null;if(current.kind==='item'&&current.moved){pushHistory(current.before);update();}else if(current.moved){saveSoon();}else if(!cancelled&&current.kind==='item'&&['switch','spdt'].includes(getComponent(current.id)?.type)){const now=event.timeStamp,previous=lastSwitchClick;if(previous?.id===current.id&&previous.tool===tool&&now-previous.time<=500&&Math.hypot(event.clientX-previous.x,event.clientY-previous.y)<=6)toggleSwitch(current.id);else lastSwitchClick={id:current.id,time:now,x:event.clientX,y:event.clientY,tool};}else if(!cancelled&&current.kind==='blank'){if(tool==='junction')placeJunction(pointFromEvent(event));else if(tool==='select'){selected=null;renderBoard();renderProperties();}}}
$('board').addEventListener('pointerup',e=>finishGesture(e));$('board').addEventListener('pointercancel',e=>finishGesture(e,true));
$('board').addEventListener('wheel',e=>{e.preventDefault();setZoom(zoom*Math.exp(-e.deltaY*.0012),e);},{passive:false});
$('board').addEventListener('keydown',event=>{const terminal=event.target.closest('[data-terminal]'),node=event.target.closest('[data-junction]'),comp=event.target.closest('[data-component]'),wire=event.target.closest('[data-wire]'),id=node?.dataset.junction??comp?.dataset.component??wire?.dataset.wire??terminal?.dataset.ownerComponent;if(['Enter',' '].includes(event.key)){event.preventDefault();if(tool==='erase')deleteSelected(id);else if(tool==='junction'&&terminal)connectTerminal(terminal.dataset.terminal);else if(tool==='junction'&&wire){const p=wirePoints(getWire(wire.dataset.wire),terminalPoint);if(p.length>1)placeJunction({x:(p[0].x+p[1].x)/2,y:(p[0].y+p[1].y)/2},wire.dataset.wire);}else select(id);}if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(event.key)&&id&&getItem(id)&&tool!=='erase'){event.preventDefault();pushHistory();const item=getItem(id);item.x+=event.key==='ArrowRight'?10:event.key==='ArrowLeft'?-10:0;item.y+=event.key==='ArrowDown'?10:event.key==='ArrowUp'?-10:0;clearRoutes(id);selected=id;update();$('board').querySelector(`[${node?'data-junction':'data-component'}="${id}"]`)?.focus({preventScroll:true});}});

function setCanvasExpanded(value){canvasExpanded=value;document.querySelector('.workspace').classList.toggle('is-fullscreen',value);document.body.classList.toggle('canvas-expanded',value);$('fullscreenButton').innerHTML=icon(value?'collapse':'expand');$('fullscreenButton').setAttribute('aria-label',value?'退出全屏工作台':'全屏工作台');$('fullscreenButton').setAttribute('aria-pressed',String(value));$('fullscreenButton').title=value?'退出全屏 (Esc)':'全屏工作台 (F)';$('fullscreenHint').hidden=!value;updateViewport();if(!value)fullscreenFocus?.focus?.({preventScroll:true});}
async function exitFullscreen(){if(document.fullscreenElement===document.querySelector('.workspace'))try{await document.exitFullscreen();}catch{}nativeFullscreen=false;setCanvasExpanded(false);}
async function toggleFullscreen(){if(canvasExpanded){await exitFullscreen();return;}fullscreenFocus=document.activeElement;setCanvasExpanded(true);if(document.fullscreenEnabled)try{await document.querySelector('.workspace').requestFullscreen();}catch{}}
document.addEventListener('fullscreenchange',()=>{if(document.fullscreenElement===document.querySelector('.workspace')){nativeFullscreen=true;setCanvasExpanded(true);}else if(nativeFullscreen){nativeFullscreen=false;setCanvasExpanded(false);}});
new ResizeObserver(()=>updateViewport()).observe($('boardWrap'));
document.addEventListener('keydown',event=>{const key=event.key.toLowerCase(),mod=event.ctrlKey||event.metaKey;if(mod&&key==='s'){event.preventDefault();if(!document.querySelector('dialog[open]'))saveExperiment();return;}if(event.key==='Escape'&&!document.querySelector('dialog[open]')){if(pendingTerminal){pendingTerminal=null;renderPreview();return;}if(canvasExpanded){event.preventDefault();exitFullscreen();return;}closeMenu();document.body.classList.remove('sidebar-open');}const typing=['TEXTAREA','SELECT'].includes(event.target.tagName)||(event.target.tagName==='INPUT'&&!['range','checkbox'].includes(event.target.type));if(typing||document.querySelector('dialog[open]'))return;if(mod&&key==='z'){event.preventDefault();event.shiftKey?redoAction():undoAction();return;}if(mod&&key==='y'){event.preventDefault();redoAction();return;}if(!mod){if(key==='v')setTool('select');if(key==='j'||key==='w')setTool('junction');if(key==='e')setTool('erase');if(key==='f'){event.preventDefault();toggleFullscreen();}if(key==='0')fitAll();if(['Delete','Backspace'].includes(event.key)&&selected){event.preventDefault();deleteSelected();}}});

function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type})),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function renderData(){$('dataCount').textContent=state.records.length;if(activeTab==='chart'){renderChart();return;}const rows=state.records.map((r,i)=>`<tr><td>${String(i+1).padStart(2,'0')}</td><td>${esc(r.experiment)}</td><td>${fixed(r.voltage)}</td><td>${fixed(r.current)}</td><td>${r.resistance==null?'—':fixed(r.resistance,1)}</td><td>${esc(r.time)}</td><td><button class="row-delete" data-delete-record="${i}" aria-label="删除第 ${i+1} 条记录">${icon('trash')}</button></td></tr>`).join('');$('dataContent').innerHTML=`<div class="table-scroll"><table class="data-table"><thead><tr><th>序号</th><th>实验名称</th><th>电源电压 U / V</th><th>总电流 I / A</th><th>等效电阻 R / Ω</th><th>记录时间</th><th></th></tr></thead><tbody>${rows}</tbody></table></div>`+(rows?'':`<div class="data-empty">${icon('notebook')}点击「记录本次数据」，保存你对电路的观察。</div>`);}
function renderChart(){const records=state.records,W=520,H=190,L=45,R=17,T=18,B=33;if(!records.length){$('dataContent').innerHTML='<div class="data-empty" style="min-height:150px">记录数据后，在这里比较电压和电流的关系。</div>';return;}const maxU=Math.max(1,...records.map(r=>r.voltage))*1.15,maxI=Math.max(.1,...records.map(r=>r.current))*1.15,x=u=>L+u/maxU*(W-L-R),y=i=>H-B-i/maxI*(H-T-B);const grid=Array.from({length:5},(_,n)=>{const yy=T+n/4*(H-T-B);return `<path d="M${L} ${yy}H${W-R}" stroke="#efebf6"/><text x="${L-9}" y="${yy+3}" text-anchor="end" fill="#aaa0b7" font-size="9">${fixed(maxI*(1-n/4))}</text><text x="${L+n/4*(W-L-R)}" y="${H-B+18}" text-anchor="middle" fill="#aaa0b7" font-size="9">${fixed(maxU*n/4,1)}</text>`;}).join(''),dots=records.map((r,i)=>`<circle cx="${x(r.voltage)}" cy="${y(r.current)}" r="4" fill="#9b7bd5" stroke="white"><title>记录 ${i+1}：${fixed(r.voltage)} V，${fixed(r.current)} A</title></circle>`).join('');$('dataContent').innerHTML=`<div class="chart-wrap"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="电压与电流的实验散点图">${grid}<path d="M${L} ${T}V${H-B}H${W-R}" stroke="#d6cddd" fill="none"/>${dots}<text x="9" y="12" fill="#a397b0" font-size="9">I / A</text><text x="${W-27}" y="${H-1}" fill="#a397b0" font-size="9">U / V</text></svg><div class="chart-note"><strong>从数据中，发现规律。</strong>保持同一个电路和电阻值不变，再改变电源电压，观察电流如何变化。<div class="chart-legend"><span></span>${records.length} 次已记录的观察</div></div></div>`;}

const guideText={help:{title:'你的电路实验工具箱',intro:'从一个元件开始，也可以载入指南中的示例。实验列表只显示你亲自保存的实验。',steps:['选择模式只选择和移动元件、节点与导线；删除模式只删除目标。拖动空白处，在没有边界的画布中移动。','接线节点模式：点击空白处放节点，点击节点或元件接线端开始连线，再点击另一个接线端完成。连接途中点击空白处创建终点节点并完成本次连线，继续接线时重新点击起点。点击导线可插入分支节点。','元件属性在右侧调整。电流表串联，电压表并联；双击开关快速通断，双击双掷开关切换支路 1 / 2，也可以在属性里切换。电铃、风扇与电热丝会按通电功率反馈。可以添加多节电池，串联时电压相加，反接时相减；同电压电池可并联。','点击保存实验，为它命名并加入左侧列表；可以新建、重命名、归档与删除。归档内容在设置中恢复，删除需要再次确认。'],formula:''},series:{title:'探索串联电路',intro:'电流沿一条路径依次流过元件。',steps:['载入示例后，比较灯泡、电阻的电流与电压。','改变电阻值，观察灯泡亮度与总电流。','选中开关，在右侧断开，再观察读数。'],formula:'I = I₁ = I₂ · U = U₁ + U₂ · R = R₁ + R₂'},parallel:{title:'探索并联电路',intro:'电流在分支节点处分配。',steps:['比较两盏灯泡的端电压和支路电流。','将一个灯泡的电阻改为 50 Ω，比较明暗差异。','在节点处增加一条支路，观察干路电流变化。'],formula:'U = U₁ = U₂ · I = I₁ + I₂'},ohm:{title:'探究欧姆定律',intro:'保持电阻不变，电流随电压成比例变化。',steps:['保持电阻 20 Ω，依次调整电压到 2 V、4 V、6 V。','每次点击记录数据，切换图表比较各次观察。','保持电压不变，改变电阻，观察电流变化。'],formula:'I = U / R'}};
function showGuide(name='help'){activeGuide=name;const g=guideText[name];document.querySelectorAll('[data-guide]').forEach(el=>el.classList.toggle('active',el.dataset.guide===name));$('guideContent').innerHTML=`<div class="guide-content"><h3>${g.title}</h3><p>${g.intro}</p><ol>${g.steps.map(s=>`<li>${s}</li>`).join('')}</ol>${g.formula?`<div class="guide-formula">${g.formula}</div>`:'<div class="guide-shortcuts"><span><kbd>V / J / E</kbd>选择、节点、删除</span><span><kbd>Ctrl+Z</kbd>撤销</span><span><kbd>Ctrl+Shift+Z</kbd>重做</span><span><kbd>Ctrl+S</kbd>保存实验</span><span><kbd>F / Esc</kbd>全屏、退出</span><span><kbd>0</kbd>适应画布</span></div>'}<div class="guide-model">灯泡、电铃、电动机及电热丝以电阻近似，声音、转速、亮度与红热程度用于定性观察。电容稳态断路，理想线圈稳态短路，不模拟暂态。普通导线交叉不会接通，实心节点处的支路互相接通。</div></div>`;$('startGuideExperiment').innerHTML=(name==='help'?'回到实验室':'载入示例')+icon('arrow-right');openDialog('guideDialog');}

function closeMenu(){$('experimentMenu').hidden=true;menuId=null;}
$('experimentList').addEventListener('click',event=>{const open=event.target.closest('[data-open-experiment]'),more=event.target.closest('[data-doc-menu]');if(open)openExperiment(open.dataset.openExperiment);if(more){menuId=more.dataset.docMenu;const r=more.getBoundingClientRect();$('experimentMenu').style.left=`${Math.min(window.innerWidth-180,r.left)}px`;$('experimentMenu').style.top=`${Math.min(window.innerHeight-130,r.bottom+5)}px`;$('experimentMenu').hidden=false;}});
$('experimentMenu').onclick=event=>{const button=event.target.closest('[data-doc-action]');if(!button)return;const id=menuId;closeMenu();if(button.dataset.docAction==='rename')renameExperiment(id);if(button.dataset.docAction==='archive')archiveExperiment(id);if(button.dataset.docAction==='delete')deleteExperiment(id);};
document.addEventListener('click',event=>{if(!event.target.closest('#experimentMenu,[data-doc-menu]'))closeMenu();});
$('newExperimentButton').onclick=newExperiment;$('saveExperimentButton').onclick=saveExperiment;$('renameActiveButton').onclick=()=>renameExperiment();
$('nameForm').onsubmit=event=>{event.preventDefault();const name=$('experimentNameInput').value.trim();if(!name){$('experimentNameInput').focus();return;}$('nameDialog').close();nameCallback?.(name);};
$('confirmAction').onclick=()=>{$('confirmDialog').close();const action=confirmCallback;confirmCallback=null;action?.();};
document.querySelectorAll('[data-close]').forEach(el=>el.onclick=()=>$(el.dataset.close).close());
document.querySelectorAll('button[data-tool]').forEach(el=>el.onclick=()=>setTool(el.dataset.tool));$('undoButton').onclick=undoAction;$('redoButton').onclick=redoAction;
$('zoomIn').onclick=()=>setZoom(zoom*1.15);$('zoomOut').onclick=()=>setZoom(zoom/1.15);$('fitButton').onclick=fitAll;$('fullscreenButton').onclick=toggleFullscreen;
$('currentToggle').checked=state.showCurrent;$('currentToggle').onchange=()=>{state.showCurrent=$('currentToggle').checked;renderBoard();saveSoon();};
$('componentLibrary').onclick=event=>{const el=event.target.closest('[data-add]');if(el)addComponent(el.dataset.add);};$('componentLibrary').ondragstart=event=>{const el=event.target.closest('[data-add]');if(el){event.dataTransfer.setData('text/circuit-component',el.dataset.add);event.dataTransfer.effectAllowed='copy';}};
$('boardWrap').ondragover=event=>event.preventDefault();$('boardWrap').ondrop=event=>{event.preventDefault();addComponent(event.dataTransfer.getData('text/circuit-component'),pointFromEvent(event));};
$('checkButton').onclick=()=>toast(solution.message);
$('clearButton').onclick=()=>confirmAction('清空当前实验画布？','元件、节点与导线将被移除，测量数据会保留。可以通过撤销恢复。',()=>{pushHistory();state=createPreset('free',state.records);selected=null;pendingTerminal=null;update();},'清空画布');
$('sidebarToggle').onclick=()=>document.body.classList.toggle('sidebar-open');$('sidebarScrim').onclick=()=>document.body.classList.remove('sidebar-open');
$('settingsButton').onclick=()=>{setSettingsTab('preferences');$('soundSetting').checked=store.data.settings.sound;$('motionSetting').checked=store.data.settings.motion;$('volumeSetting').value=Math.round(store.data.settings.volume*100);$('volumeValue').textContent=$('volumeSetting').value+'%';$('recoverDraftButton').hidden=!store.data.draft;openDialog('settingsDialog');};
document.querySelectorAll('[data-settings-tab]').forEach(el=>el.onclick=()=>setSettingsTab(el.dataset.settingsTab));
for(const id of ['soundSetting','motionSetting','volumeSetting'])$(id).oninput=()=>{const next={sound:$('soundSetting').checked,motion:$('motionSetting').checked,volume:Number($('volumeSetting').value)/100};try{store.settings(next);}catch{Object.assign(store.data.settings,next);toast('设置暂未保存');}$('volumeValue').textContent=$('volumeSetting').value+'%';renderAudioState();renderBoard();audio.sync(state.components,solution.components,store.data.settings);};
$('archivedList').onclick=event=>{const restore=event.target.closest('[data-restore-experiment]'),del=event.target.closest('[data-delete-experiment]');if(restore){if(tryStore(()=>store.restore(restore.dataset.restoreExperiment)))toast('实验已恢复到列表');}if(del)deleteExperiment(del.dataset.deleteExperiment);};
$('backupExportButton').onclick=()=>{persist();const backup=clone(store.data);const current=backup.experiments.find(e=>e.id===activeId);if(current)current.state=snapshot();else{backup.draft=snapshot();backup.draftName=draftName;}download(JSON.stringify(backup,null,2),`电路实验备份-${new Date().toLocaleDateString('sv-SE')}.json`,'application/json');};
$('backupImportButton').onclick=()=>$('backupFile').click();$('backupFile').onchange=async()=>{const file=$('backupFile').files[0];if(!file)return;try{if(file.size>20*1024*1024)throw new Error('备份文件过大');const backup=JSON.parse(await file.text());if(!normalizeCollection(backup))throw new Error('备份格式不正确');if(tryStore(()=>store.import(backup))){activeId=store.data.activeId;restoreState(store.data.experiments.find(e=>e.id===activeId)?.state??store.data.draft??createPreset('free'));toast('实验备份已导入');}}catch(error){toast(error.message);}$('backupFile').value='';};
$('guideButton').onclick=$('helpButton').onclick=()=>showGuide('help');document.querySelectorAll('[data-guide]').forEach(el=>el.onclick=()=>showGuide(el.dataset.guide));$('startGuideExperiment').onclick=()=>{$('guideDialog').close();if(activeGuide!=='help'){pushHistory();state=createPreset(activeGuide,state.records);selected=null;pendingTerminal=null;camera={x:420,y:255};zoom=1;update();renderData();}};
document.querySelectorAll('[data-tab]').forEach(el=>el.onclick=()=>{activeTab=el.dataset.tab;document.querySelectorAll('[data-tab]').forEach(tab=>tab.classList.toggle('active',tab===el));renderData();});
$('recordButton').onclick=()=>{if(solution.status!=='ok'){toast('先连接完整电路，再记录测量数据');return;}if(solution.sourceVoltage==null){toast('此电路没有唯一的总电压，请用电压表分别测量。');return;}if(state.records.length>=500){toast('请先导出已有数据');return;}state.records.push({experiment:activeId?title():{series:'串联电路',parallel:'并联电路',ohm:'欧姆定律',free:'自由搭建'}[state.preset],voltage:solution.sourceVoltage,current:solution.current,resistance:solution.resistance,time:new Date().toLocaleTimeString('zh-CN',{hour12:false}),createdAt:new Date().toISOString(),circuit:clone({components:state.components,wires:state.wires,junctions:state.junctions})});renderData();saveSoon();toast('已记录本次观察');};
$('dataContent').onclick=event=>{const el=event.target.closest('[data-delete-record]');if(el){state.records.splice(Number(el.dataset.deleteRecord),1);renderData();saveSoon();}};
$('exportButton').onclick=()=>{if(!state.records.length){toast('先记录测量数据后即可导出');return;}const cell=v=>'"'+String(v??'').replaceAll('"','""')+'"',rows=[['序号','实验名称','电源电压(V)','总电流(A)','等效电阻(Ω)','记录时间'],...state.records.map((r,i)=>[i+1,r.experiment,r.voltage,r.current,r.resistance,r.createdAt])];download('\uFEFF'+rows.map(row=>row.map(cell).join(',')).join('\r\n'),'电路实验数据.csv','text/csv;charset=utf-8');};
document.addEventListener('visibilitychange',()=>{if(document.hidden){audio.silence();stopFanFrames();}else{audio.sync(state.components,solution.components,store.data.settings);startFanFrames();}});
window.addEventListener('pagehide',()=>{persist();audio.dispose();stopFanFrames();});
window.addEventListener('pageshow',()=>{audio.sync(state.components,solution.components,store.data.settings);startFanFrames();});
window.addEventListener('storage',event=>{if(event.key!=='circuit-lab-experiments-v2')return;try{const next=normalizeCollection(JSON.parse(event.newValue));if(!next)return;if(activeId&&!next.experiments.some(e=>e.id===activeId&&!e.archived)){activeId=null;toast('当前实验已在其他页面归档或删除，编辑内容保留为草稿。');}next.activeId=activeId;store.data=next;renderSidebar();renderTitle();renderArchives();}catch{}});
renderLibrary();renderSidebar();renderTitle();setTool('select');update();renderData();renderArchives();renderAudioState();

$('recoverDraftButton').onclick=()=>{persist();const draft=store.data.draft;if(!draft)return;activeId=null;store.data.activeId=null;draftName=store.data.draftName;restoreState(draft);$('settingsDialog').close();toast('已恢复未保存的草稿');};
